MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  register ssize_t
    i;

  size_t
    length;

  StringInfo
    *blob;

  char
    *base64_data;

  assert(image_info != (ImageInfo *) NULL);
  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);

  if (LogImageTypeInfo != (LogImageTypeInfo) NULL)
    LogImageTypeInfo("INLINE",image_info,"enter",image);

  magick_info=GetMagickInfo("INLINE",image_info->blob_bits ?
    image_info->blob_bits->name : (const char *) NULL);
  if (magick_info == (MagickInfo *) NULL)
    return(MagickFalse);

  clone_image=CloneImage(image,0,0,MagickTrue,"unable to write INLINE image");
  if (clone_image == (Image *) NULL)
    return(MagickFalse);

  clone_image->storage_class=DirectClass;
  clone_image->colorspace=RGBColorspace;

  blob=BlobToBase64(clone_image);
  if (blob == (StringInfo *) NULL)
    return(MagickFalse);

  length=GetStringInfoLength(blob);
  base64_data=(char *) MagickAllocateMemory(GetStringInfoBlob(blob),length+1);
  if (base64_data == (char *) NULL)
    return(MagickFalse);

  for (i=0; i < (ssize_t) length; i++)
    base64_data[i]=(char) (GetStringInfoBlob(blob)[i]);

  base64_data[length]='\0';

  status=WriteBlobString(image,base64_data);

  MagickFreeMemory(base64_data);
  DestroyBlob(clone_image);

  return(status);
}

