MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image) {
  MagickBooleanType status;
  Image *clone_image;
  MagickInfo *magick_info;
  StringInfo *blob;
  size_t length;
  char *base64, *base64_end;

  if ((image_info == (ImageInfo *) NULL) || (image == (Image *) NULL))
    return MagickFalse;

  if (GetLogEventLogging() != MagickFalse)
    (void) LogMagickEvent(CoderEvent, GetMagickModule(), "filename: %s",
      image_info->filename);

  magick_info = GetMagickInfo("INLINE", (ExceptionInfo *) NULL);
  if (magick_info == (MagickInfo *) NULL)
    return MagickFalse;

  clone_image = CloneImage(image, image->columns, image->rows, MagickTrue,
    (ExceptionInfo *) NULL);
  if (clone_image == (Image *) NULL)
    return MagickFalse;

  status = ConvertImage(clone_image, &blob, (ExceptionInfo *) NULL);
  if (status == MagickFalse) {
    DestroyImage(clone_image);
    return MagickFalse;
  }

  length = Base64EncodeBlob((const unsigned char *) StringInfoDatum(blob),
    StringInfoLength(blob), &base64);
  if (length == 0) {
    DestroyImage(clone_image);
    RelinquishMagickMemory(base64);
    return MagickFalse;
  }

  blob = AcquireStringInfo(length);
  (void) memcpy(StringInfoDatum(blob), base64, length);
  RelinquishMagickMemory(base64);

  status = OpenBlob(image_info, blob, WriteBinaryBlob, (ExceptionInfo *) NULL);
  if (status == MagickFalse) {
    DestroyImage(clone_image);
    RelinquishMagickMemory(base64);
    return MagickFalse;
  }

  base64_end = (char *) StringInfoDatum(blob) + StringInfoLength(blob);
  status = WriteBlob(image_info, base64_end - base64, base64, (ExceptionInfo *) NULL);
  if (status == MagickFalse) {
    DestroyImage(clone_image);
    RelinquishMagickMemory(base64);
    return MagickFalse;
  }

  DestroyImage(clone_image);
  RelinquishMagickMemory(base64);
  CloseBlob(blob);
  return MagickTrue;
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  char
    *base64_data;

  size_t
    length;

  size_t
    count;

  MagickStatusType
    flags;

  clone_image = CloneImage(image, image->columns, image->rows, MagickFalse, exceptionInfo());
  if (clone_image == (Image *) NULL)
    return(MagickFalse);

  magick_info = GetMagickInfo("INLINE", exceptionInfo());
  if (magick_info == (MagickInfo *) NULL)
    return(MagickFalse);

  if (image_info->debug != MagickFalse)
    (void) LogMagickEvent(CoderEvent, GetMagickModule(), "Writing INLINE image");

  if (GetImageProperty("format:INLINE", clone_image) != (const char *) NULL)
    (void) CloneImage(clone_image, clone_image->columns, clone_image->rows, MagickFalse, exceptionInfo());

  status = MagickTrue;
  base64_data = (char *) NULL;
  length = 0;

  flags = 0;
  if (clone_image->storage_class == PseudoClass)
    flags |= MagickNormalize;

  if (WriteBlobBase64(clone_image, clone_image->columns, clone_image->rows,
                       clone_image->depth, clone_image->storage_class,
                       clone_image->colorspace, clone_image->matte, clone_image->page,
                       clone_image->units, clone_image->orientation,
                       clone_image->montage, clone_image->taint, flags, &base64_data,
                       &length) != MagickFalse)
  {
    count = strlen(base64_data);
    if (count != length)
      length = count;

    if (length != 0)
    {
      status = MagickWriteBlobImage(clone_image, base64_data, length, exceptionInfo());
      base64_data = (char *) RelinquishMemory(base64_data);
    }
  }

  if (status != MagickFalse)
    status = MagickTrue;

  DestroyImage(clone_image);
  return(status);
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  char
    *base64_data;

  size_t
    length;

  assert(image_info != (ImageInfo *) NULL);
  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);

  if (image->debug != MagickFalse)
    (void) LogMagickEvent(CoderEvent, __func__, "Enter");

  magick_info = GetMagickInfo("INLINE", &image->exception);
  if (magick_info == (MagickInfo *) NULL)
  {
    (void) ThrowMagickException(&image->exception, GetMagickModule(), CoderError,
      "UnableToFindCoder", "INLINE");
    return MagickFalse;
  }

  clone_image = CloneImage(image, image->columns, image->rows, MagickFalse,
    &image->exception);
  if (clone_image == (Image *) NULL)
    return MagickFalse;

  status = ConvertImage(clone_image, &length, (void **) &base64_data,
    MagickTrue, &image->exception);
  if (status == MagickFalse)
  {
    (void) DestroyImage(clone_image);
    return MagickFalse;
  }

  base64_data = (char *) Base64Encode(base64_data, length, &length);

  (void) OpenBlob(image_info, image, WriteBlob, &image->exception);
  if (image->blob == (BlobInfo *) NULL)
  {
    (void) DestroyImage(clone_image);
    (void) free(base64_data);
    return MagickFalse;
  }

  status = WriteBlob(image, length, base64_data);

  (void) CloseBlob(image);
  (void) DestroyImage(clone_image);
  (void) free(base64_data);

  if (image->debug != MagickFalse)
    (void) LogMagickEvent(CoderEvent, __func__, "Leave");

  return status;
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image)
{
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  MemoryInfo
    *memory_info;

  register ssize_t
    i;

  size_t
    length;

  StringInfo
    *string_info;

  assert(image_info != (ImageInfo *) NULL);
  assert(image_info->signature == MagickSignature);
  assert(image != (Image *) NULL);
  assert(image->signature == MagickSignature);

  if (LocaleCompare(image_info->format,"INLINE") != 0)
    {
      magick_info=AcquireMagickInfo("INLINE",image_info->filename,"INLINE");
      if (magick_info == (MagickInfo *) NULL)
        return(MagickFalse);
    }

  clone_image=CloneImage(image,0,0,MagickTrue,"unable to write inline image");
  if (clone_image == (Image *) NULL)
    return(MagickFalse);

  status=BlobImage(clone_image,0);
  if (status == MagickFalse)
    {
      clone_image=DestroyImage(clone_image);
      return(status);
    }

  length=Base64EncodeBlob(clone_image->blob->length,clone_image->blob->data);
  memory_info=AcquireMemoryInfo(length);
  if (memory_info == (MemoryInfo *) NULL)
    {
      clone_image=DestroyImage(clone_image);
      return(MagickFalse);
    }

  Base64Encode(clone_image->blob->length,clone_image->blob->data,
    (unsigned char *) memory_info->data);

  string_info=CloneStringInfo(memory_info->data);
  if (string_info == (StringInfo *) NULL)
    {
      RelinquishMemory(memory_info);
      clone_image=DestroyImage(clone_image);
      return(MagickFalse);
    }

  (void) SetImageBlob(clone_image,string_info,clone_image->blob->length);

  RelinquishMemory(memory_info);
  clone_image=DestroyImage(clone_image);

  return(MagickTrue);
}
